  WORD_LOCAL(f, 0xc);
  BYTE_LOCAL(g, 0xe);
  BUFFER(h, 0x1a);
  BUFFER(i, 0x26);
  BYTE_LOCAL(j, 0x28);
  STOCK_P k;
  TEXT_P  l;
  TEXT_P  m;
  TITLE(UNIT_NAME(unit, h));
  CAPACITIES(unit, AT(a), AT(f), AT(e));
  SET(a, PERCENT(UNIT_AMMO(unit), VALUE(a)));
  SET(f, PERCENT(UNIT_FUEL(unit), VALUE(f)));
  SET(e, PERCENT(UNIT_FOOD(unit), VALUE(e)));
  d = DESTINATION(unit, AT(g), AT(j));
  POSITION(0x2d, 0xa3);
  l = d ? ORDER_NAME(unit) : WAITING;
  PRINT4(ORDERS, l, UNIT_FUEL(unit), VALUE(f));
  POSITION(0x2d, 0xb4);
  m = d ? LOCATION(BYTE_VALUE(g), BYTE_VALUE(j), i)
        : LOCATION(UNIT_X(unit), UNIT_Y(unit), i);
  PRINT4(TARGET, m, UNIT_AMMO(unit), VALUE(a));
  POSITION(0x2d, 0xc5);
  PRINT4(FATIGUE_ROW, FATIGUE(unit), UNIT_FOOD(unit), VALUE(e));
  for (c = FIRST_ELEMENT(unit), b = 0; c; c = NEXT_ELEMENT(c), b++) {
    POSITION(ELEMENT_X(b), ELEMENT_Y(b));
    k = ELEMENT_ITEM(c);
    PRINT3(ELEMENT_ROW, TYPE_NAME(k), STOCK_AMOUNT(k));
  }
